-- | Golden differential goldens for the wire conformance corpus (M3 plan
-- D8/D16), the @cabal test@ half of the N11 differential anchor.
--
-- The committed fixtures under @fixtures/@ (the two self-edge fixtures),
-- @fixtures/corpus/@ (generated by @scripts/gen-corpus.hs@), and the eight
-- worked-example anchors @examples/<NAME>/example.core.sexp@ (generated by
-- @scripts/gen-worked-examples.hs@) are the single
-- source of truth. Each is decoded and run through the real Haskell pipeline
-- ('Lara.Driver.runUnit'); the printed verdict must equal the pinned golden
-- bytes — the exact bytes __both__ drivers emit, cross-checked against the Lean
-- executable semantics by @scripts/differential.sh@ (the real both-drivers
-- differential). Pinning them here lets plain @cabal test@ catch regressions
-- without the Lean binary present.
--
-- The fixtures are also guarded to be canonical: @printSExpr (encodeUnit u)@ of
-- the decoded unit must reproduce the committed bytes, so a hand-edit that is
-- not canonical wire text is rejected.
--
-- Arbitration (plan Global Constraints): the Lean executable is the oracle.
-- These goldens are the agreed bytes; if @differential.sh@ ever shows Lean
-- disagreeing, that is a bug fixed with a recorded note — never a silent
-- re-annotation of a golden here.
--
-- This module reads the fixture files by relative path, so the suite must be
-- run from the package root (as @cabal test@ does).
module DifferentialSpec (differentialSpecProps) where

import Test.QuickCheck

import Lara.AST
  ( AtomPat (..)
  , Contrary (..)
  , Exception (..)
  , Label (..)
  , Pat (..)
  , Question (..)
  , Rule (..)
  , Status (..)
  , SupportTerm (..)
  , Unit (..)
  )
import Lara.Driver (runUnit)
import Lara.Prop (Prop (..), Term (..))
import Lara.Wire
  ( Verdict (..)
  , decodeUnitFile
  , encodeUnit
  , encodeVerdict
  , printSExpr
  )

