stressFixture :: FilePath
stressFixture = "fixtures/corpus/stress-independent-120.sexp"

-- ---------------------------------------------------------------------------
-- Verdict goldens
-- ---------------------------------------------------------------------------

-- | Every corpus fixture decodes and prints exactly its pinned verdict bytes.
prop_corpusVerdicts :: Property
prop_corpusVerdicts = once (ioProperty runChecks)
  where
    runChecks :: IO Property
    runChecks = conjoin <$> mapM checkOne corpusGoldens
    checkOne (path, golden) = do
      s <- readFile path
      let got = case decodeUnitFile s of
            Left e -> "CODEC:" ++ show e
            Right u -> printSExpr (encodeVerdict (runUnit u))
      pure (counterexample path (got === golden))

-- | Every committed fixture is canonical wire text: re-encoding the decoded
-- unit reproduces the file bytes (modulo the single trailing newline).
prop_corpusCanonical :: Property
prop_corpusCanonical = once (ioProperty runChecks)
  where
    paths = stressFixture : map fst corpusGoldens
    runChecks :: IO Property
    runChecks = conjoin <$> mapM checkOne paths
    checkOne path = do
      s <- readFile path
      let reencoded = case decodeUnitFile s of
            Left e -> "CODEC:" ++ show e
            Right u -> printSExpr (encodeUnit u) ++ "\n"
      pure (counterexample path (reencoded === s))

-- ---------------------------------------------------------------------------
-- Numeric-literal canonicalization guard (M3 review item 7)
-- ---------------------------------------------------------------------------

-- | Every numeric literal ('TNum') reachable in a unit. 'encodeTerm' reprints a
-- 'TNum' verbatim, so a non-canonical @(num 01)@ round-trips byte-exactly and
-- passes 'prop_corpusCanonical' — yet the Lean driver runs at @canon = id@ while
-- the Haskell core canonicalizes, so the two drivers /diverge/ on it. The corpus
-- policy is therefore to carry no @num@ literals at all (see @scripts/gen-corpus.hs@).
numLiteralsInUnit :: Unit -> [String]
numLiteralsInUnit u =
  concatMap numsInRule (unitRules u)
    ++ concatMap numsInContrary (unitContraries u)
    ++ concatMap numsInException (unitExceptions u)
    ++ concatMap (concatMap numsInProp . snd) (unitTheories u)
    ++ concatMap (numsInProp . snd) (unitLeaves u)
    ++ concatMap (numsInST . snd) (unitArgs u)
    ++ concatMap numsInProp (unitQueries u)
  where
    numsInTerm t = case t of
      TNum s -> [s]
      TStr _ -> []
      TCon _ ts -> concatMap numsInTerm ts
    numsInPat p = case p of
      PVar _ -> []
      PLit t -> numsInTerm t
      PCon _ ps -> concatMap numsInPat ps
    numsInAPat (AtomPat _ ps) = concatMap numsInPat ps
    numsInProp (Prop _ ts) = concatMap numsInTerm ts
    numsInRule r =
      concatMap numsInAPat (rulePremises r)
        ++ numsInAPat (ruleConclusion r)
        ++ concatMap (numsInAPat . questionAnswer) (ruleQuestions r)
    numsInContrary (Contrary a b) = numsInAPat a ++ numsInAPat b
    numsInException (Exception _ ap) = numsInAPat ap
    numsInST t = case t of
      SLeaf _ -> []
      SRule _ theta prems disch _ _ ->
        concatMap (numsInTerm . snd) theta
          ++ concatMap numsInST prems
          ++ concatMap (numsInST . snd) disch

-- | No committed fixture carries any @num@ literal — the executable form of the
-- num-free corpus policy. This is the guard 'prop_corpusCanonical' cannot be:
-- a hand-added @(num 01)@ re-encodes to itself and slips past canonicity, but
-- diverges between the drivers, so it must be rejected structurally here.
prop_corpusNoNumLiterals :: Property
prop_corpusNoNumLiterals = once (ioProperty runChecks)
  where
    paths = stressFixture : map fst corpusGoldens
    runChecks :: IO Property
    runChecks = conjoin <$> mapM checkOne paths
    checkOne path = do
      s <- readFile path
      pure $ case decodeUnitFile s of
        Left e -> counterexample (path ++ ": CODEC:" ++ show e) (property False)
        Right u ->
          let nums = numLiteralsInUnit u
           in counterexample
                (path ++ ": non-policy num literals " ++ show nums)
                (nums === [])

-- | The 120-argument stress fixture: 120 independent leaf arguments, all @in@,
-- no compiled edges, 120 @justified@ statuses. Checked structurally to avoid a
-- multi-kilobyte literal golden; @scripts/differential.sh@ confirms Lean agrees
-- byte-exact.
prop_stressAccept :: Property
prop_stressAccept = once (ioProperty check)
  where
    check :: IO Property
    check = do
      s <- readFile stressFixture
      pure $ case decodeUnitFile s of
        Left e -> counterexample ("CODEC:" ++ show e) False
        Right u -> case runUnit u of
          VReject r -> counterexample ("unexpected reject: " ++ show r) (property False)
          VAccept lbls edges statuses ->
            conjoin
              [ counterexample "label count" (length lbls === 120)
              , counterexample "all in" (property (all ((== LIn) . snd) lbls))
              , counterexample "no edges" (edges === [])
              , counterexample "status count" (length statuses === 120)
              , counterexample "all justified" (property (all ((== Justified) . snd) statuses))
              ]

-- ---------------------------------------------------------------------------
-- Index
-- ---------------------------------------------------------------------------

differentialSpecProps :: [(String, IO Result)]
differentialSpecProps =
  [ ("differential corpus verdict goldens", quickCheckResult prop_corpusVerdicts)
  , ("differential corpus fixtures canonical", quickCheckResult prop_corpusCanonical)
  , ("differential corpus carries no num literals", quickCheckResult prop_corpusNoNumLiterals)
  , ("differential 120-arg stress accept", quickCheckResult prop_stressAccept)
  ]
